-- The NCLEX-RN, Weiterbildung and CCM pathways: their statuses, the document
-- types their requirements name, and the requirements. Run in psql on the VPS
-- (or the SQL editor) after migration 0088 and before the code that offers the
-- pathways goes out. Safe to run twice: nothing already in the database is
-- changed. Generated by scripts/new-pathways-sql.ts; the Weiterbildung and CCM
-- rows are provisional until the written guides for them arrive.
BEGIN;

-- Statuses. A code already there is left exactly as it is, label and order included.

-- Document types the requirements below name, inserted only where missing.

-- Requirements. Guarded by type, source and pathway: a document is asked for once
-- per pathway, and a row the team has since edited is left as it is.

COMMIT;

-- What is there now.
SELECT 'NCLEX statuses ' || count(*) FROM status_definitions WHERE pathway = 'NCLEX' AND active
UNION ALL SELECT 'NCLEX requirements ' || count(*) FROM document_requirements WHERE pathway = 'NCLEX' AND active
UNION ALL SELECT 'WEITERBILDUNG statuses ' || count(*) FROM status_definitions WHERE pathway = 'WEITERBILDUNG' AND active
UNION ALL SELECT 'WEITERBILDUNG requirements ' || count(*) FROM document_requirements WHERE pathway = 'WEITERBILDUNG' AND active
UNION ALL SELECT 'CCM statuses ' || count(*) FROM status_definitions WHERE pathway = 'CCM' AND active
UNION ALL SELECT 'CCM requirements ' || count(*) FROM document_requirements WHERE pathway = 'CCM' AND active;

